package com.example;

public class Sample {
    public void run(int n) {
        Logger log = new Logger();
        for (int i = 0; i < n; i++) {
            log.tick(i);
        }
        if (n > 0) {
            log.positive();
        } else {
            log.nonpositive();
        }
        try {
            log.risky();
        } catch (Exception e) {
            log.recover();
        }
    }
}
